var container = document.getElementById('container');
var draw = SVG().addTo(container).size('100%', '100%');

var state = { a: 6, b: 4, params: false, showP: false, theta: 0.85 };
var W = 600, H = 400, scale = 30, fs = 13;

var COL_ELL = '#1f7cb4', COL_RED = '#e02020', COL_GREEN = '#22b422',
    COL_DOT = '#000000', COL_DIM = '#004c99', COL_P = '#f08000';

/* ---------- helpers ---------- */
function T(txt, x, y, opt) {
  opt = opt || {};
  var t = draw.plain(txt);
  t.font({
    family: 'Georgia, "Times New Roman", Times, serif',
    size: opt.size || fs,
    anchor: opt.anchor || 'middle',
    style: opt.italic ? 'italic' : 'normal'
  });
  t.attr({
    x: x, y: y, 'dominant-baseline': 'middle',
    'paint-order': 'stroke', stroke: '#ffffff',
    'stroke-width': (opt.halo == null ? 3.4 : opt.halo), 'stroke-linejoin': 'round'
  });
  t.fill(opt.color || '#111111');
  return t;
}

function arrowHead(x, y, ang, s, color) {
  var pts = [[0, 0], [-s, -s * 0.42], [-s, s * 0.42]].map(function (p) {
    return [x + p[0] * Math.cos(ang) - p[1] * Math.sin(ang),
            y + p[0] * Math.sin(ang) + p[1] * Math.cos(ang)];
  });
  return draw.polygon(pts.map(function (p) { return p[0] + ',' + p[1]; }).join(' ')).fill(color);
}

function attach(el, tip, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  el.on('click', function () { showPopup(title, body); });
  return el;
}

function panel(lines, corner, size) {
  var g = draw.group();
  var sz = size || fs * 0.92;
  var lh = sz * 1.5;
  for (var i = 0; i < lines.length; i++) {
    var t = g.plain(lines[i]);
    t.font({ family: 'Georgia, "Times New Roman", Times, serif', size: sz, anchor: 'start' });
    t.attr({ x: 0, y: i * lh, 'dominant-baseline': 'middle' });
    t.fill('#14202b');
  }
  var bb = g.bbox(), pad = sz * 0.6;
  var r = g.rect(bb.width + 2 * pad, bb.height + 2 * pad).move(bb.x - pad, bb.y - pad)
    .fill('#ffffff').opacity(0.92).stroke({ color: '#c9d2da', width: 1 }).radius(4);
  r.back();
  var bb2 = g.bbox(), m = 8;
  var tx = corner.indexOf('right') >= 0 ? (W - m - bb2.x - bb2.width) : (m - bb2.x);
  var ty = corner.indexOf('bottom') >= 0 ? (H - m - bb2.y - bb2.height) : (m - bb2.y);
  g.transform({ translate: [tx, ty] });
  return g;
}

function dimArrow(x1, y1, x2, y2, color, as) {
  draw.line(x1, y1, x2, y2).stroke({ color: color, width: 1.5 });
  var ang = Math.atan2(y2 - y1, x2 - x1);
  arrowHead(x2, y2, ang, as * 0.75, color);
  arrowHead(x1, y1, ang + Math.PI, as * 0.75, color);
}

/* ---------- layout ---------- */
function relayout() {
  var s = _containerInnerSize();
  W = Math.max(120, s.width || 600);
  H = Math.max(100, s.height || 400);
  var a = state.a, b = Math.min(state.b, state.a);
  var needX = Math.max(9.4, a + 1.9);
  var needY = Math.max(6.2, b + 1.3);
  scale = Math.min(W / (2 * needX), H / (2 * needY));
  var halfX = W / (2 * scale), halfY = H / (2 * scale);
  setPlotFrame({ xDomain: [-halfX, halfX], yDomain: [-halfY, halfY], margin: 0, draw: draw });
  fs = Math.max(8.5, Math.min(17, Math.min(W, H) / 27));
  render();
}
document.addEventListener('fig-resize', relayout);

/* ---------- main render ---------- */
function render() {
  var a = state.a, b = Math.min(state.b, a);
  var c = Math.sqrt(Math.max(0, a * a - b * b));
  draw.clear();
  draw.rect(W, H).fill('#ffffff');

  var cx = plotX(0), cy = plotY(0);
  var as = Math.max(5, Math.min(12, scale * 0.32));
  var rBig = Math.max(2.6, Math.min(6, scale * 0.115));
  var rSm = Math.max(2.2, Math.min(5, scale * 0.095));

  /* axes */
  draw.line(3, cy, W - 3, cy).stroke({ color: '#000', width: 1.3 });
  draw.line(cx, 3, cx, H - 3).stroke({ color: '#000', width: 1.3 });
  arrowHead(W - 3, cy, 0, as, '#000');
  arrowHead(3, cy, Math.PI, as, '#000');
  arrowHead(cx, 3, -Math.PI / 2, as, '#000');
  arrowHead(cx, H - 3, Math.PI / 2, as, '#000');

  /* ellipse */
  var ell = draw.ellipse(2 * a * scale, 2 * b * scale).center(cx, cy)
    .fill('none').stroke({ color: COL_ELL, width: Math.max(1.8, scale * 0.075) });
  attach(ell, 'Ellipse: r₁ + r₂ = 2a for every point',
    'The ellipse',
    'Every point of this blue curve has the same total distance to the two green foci, namely 2a — the full length of the major axis. That single rule produces the whole shape.');

  /* dashed axes segments */
  var major = draw.line(plotX(-a), cy, plotX(a), cy)
    .stroke({ color: COL_RED, width: 1.9, dasharray: '8,5' });
  attach(major, 'Major axis, length 2a = ' + (2 * a).toFixed(1),
    'Major axis',
    'The longest chord of the ellipse. It runs from vertex to vertex through the center, has length 2a, and always contains both foci.');
  var minor = draw.line(cx, plotY(-b), cx, plotY(b))
    .stroke({ color: COL_RED, width: 1.9, dasharray: '8,5' });
  attach(minor, 'Minor axis, length 2b = ' + (2 * b).toFixed(1),
    'Minor axis',
    'The shortest chord through the center, running co-vertex to co-vertex with length 2b. It is perpendicular to the major axis at the center.');

  /* foci (green) */
  if (c > 0.3) {
    [c, -c].forEach(function (fx) {
      var d = draw.circle(rSm * 2).center(plotX(fx), cy).fill(COL_GREEN).stroke({ color: '#0a7a0a', width: 0.8 });
      attach(d, 'Focus (' + fx.toFixed(2) + ', 0),  c = √(a²−b²) = ' + c.toFixed(2),
        'Focus',
        'The foci sit on the major axis at (±c, 0) with c = √(a² − b²) = ' + c.toFixed(2) +
        '. They are not free: they are fixed the moment you choose a and b.');
    });
  } else {
    var d0 = draw.circle(rSm * 2).center(cx, cy).fill(COL_GREEN).stroke({ color: '#0a7a0a', width: 0.8 });
    attach(d0, 'Both foci coincide with the center (c = 0)',
      'Foci at the center',
      'When a = b the ellipse is a circle, c = √(a² − b²) = 0, and both foci collapse onto the center.');
  }

  /* black dots */
  function dot(x, y, tip, title, body) {
    var d = draw.circle(rBig * 2).center(plotX(x), plotY(y)).fill(COL_DOT);
    attach(d, tip, title, body);
    return d;
  }
  dot(0, 0, 'Center (0, 0)', 'Center',
    'Everything is measured from here: a out to a vertex, b out to a co-vertex, c out to a focus.');
  dot(a, 0, 'Vertex (' + a.toFixed(1) + ', 0)', 'Vertex',
    'A vertex is an endpoint of the major axis, at distance a = ' + a.toFixed(1) + ' from the center.');
  dot(-a, 0, 'Vertex (−' + a.toFixed(1) + ', 0)', 'Vertex',
    'A vertex is an endpoint of the major axis, at distance a = ' + a.toFixed(1) + ' from the center.');
  dot(0, b, 'Co-vertex (0, ' + b.toFixed(1) + ')', 'Co-vertex',
    'A co-vertex is an endpoint of the minor axis, at distance b = ' + b.toFixed(1) + ' from the center.');
  dot(0, -b, 'Co-vertex (0, −' + b.toFixed(1) + ')', 'Co-vertex',
    'A co-vertex is an endpoint of the minor axis, at distance b = ' + b.toFixed(1) + ' from the center.');

  /* ---- labels ---- */
  if (!state.params) {
    T('Vertex', plotX(-a) - rBig - 5, cy - fs * 0.15, { anchor: 'end' });
    T('Vertex', plotX(a) + rBig + 5, cy - fs * 0.15, { anchor: 'start' });
    T('Co-vertex', cx + rBig + 6, plotY(b), { anchor: 'start' });
    T('Co-vertex', cx + rBig + 6, plotY(-b), { anchor: 'start' });
    if (c > 0.3) {
      T('Focus', plotX(c), cy - fs * 1.15);
      T('Focus', plotX(-c), cy - fs * 1.15);
    } else {
      T('Foci', cx, cy - fs * 1.3, { color: '#0a7a0a' });
    }
    T('Center', cx + fs * 1.5, cy + fs * 1.25, { anchor: 'middle' });
    T('Major Axis', plotX(-a / 2), cy + fs * 1.25);
    T('Minor Axis', cx + fs * 0.7, plotY(b / 2), { anchor: 'start' });
  } else {
    var offA = 0.85, offB = 0.85, offC = 0.95;
    dimArrow(cx, plotY(offA), plotX(a), plotY(offA), COL_DIM, as);
    T('a = ' + a.toFixed(1), plotX(a / 2), plotY(offA) - fs * 0.95, { color: COL_DIM, italic: true });
    dimArrow(plotX(-offB), cy, plotX(-offB), plotY(b), COL_DIM, as);
    T('b = ' + b.toFixed(1), plotX(-offB) - fs * 0.5, plotY(b / 2), { anchor: 'end', color: COL_DIM, italic: true });
    if (c > 0.3) {
      dimArrow(cx, plotY(-offC), plotX(c), plotY(-offC), '#0a8a0a', as);
      T('c = ' + c.toFixed(2), plotX(c / 2), plotY(-offC) + fs * 0.95, { color: '#0a8a0a', italic: true });
    } else {
      T('c = 0', cx + fs * 0.6, plotY(-offC), { anchor: 'start', color: '#0a8a0a', italic: true });
    }
    panel([
      'x²/a² + y²/b² = 1',
      'x²/' + (a * a).toFixed(1) + ' + y²/' + (b * b).toFixed(1) + ' = 1',
      'c² = a² − b² = ' + (a * a).toFixed(1) + ' − ' + (b * b).toFixed(1) + ' = ' + (c * c).toFixed(1),
      'a = ' + a.toFixed(1) + '   b = ' + b.toFixed(1) + '   c = ' + c.toFixed(2)
    ], 'top-left');
  }

  /* ---- draggable point P ---- */
  if (state.showP) {
    var px = a * Math.cos(state.theta), py = b * Math.sin(state.theta);
    var f1x = -c, f2x = c;
    var r1 = Math.sqrt((px - f1x) * (px - f1x) + py * py);
    var r2 = Math.sqrt((px - f2x) * (px - f2x) + py * py);
    draw.line(plotX(f1x), cy, plotX(px), plotY(py)).stroke({ color: '#777', width: 1.3 });
    draw.line(plotX(f2x), cy, plotX(px), plotY(py)).stroke({ color: '#777', width: 1.3 });
    T('r₁', (plotX(f1x) + plotX(px)) / 2, (cy + plotY(py)) / 2 - fs * 0.5, { size: fs * 0.9, color: '#444' });
    T('r₂', (plotX(f2x) + plotX(px)) / 2, (cy + plotY(py)) / 2 - fs * 0.5, { size: fs * 0.9, color: '#444' });
    var pd = draw.circle(rBig * 2.3).center(plotX(px), plotY(py))
      .fill(COL_P).stroke({ color: '#a05000', width: 1 });
    pd.css('cursor', 'grab');
    attach(pd, 'Drag me — r₁ + r₂ stays 2a = ' + (2 * a).toFixed(2),
      'Point P on the ellipse',
      'Drag P around the curve. r₁ and r₂ change, but their sum is always 2a = ' + (2 * a).toFixed(2) +
      ' — that constant sum is the definition of an ellipse.');
    panel([
      'r₁ = ' + r1.toFixed(2) + '    r₂ = ' + r2.toFixed(2),
      'r₁ + r₂ = ' + (r1 + r2).toFixed(2) + ' = 2a'
    ], 'top-right', fs * 0.9);
  }

  /* axis letters (drawn last, on top) */
  T('x', W - 5 - as - fs * 0.55, cy - fs * 0.85, { italic: true });
  T('y', cx - fs * 0.85, 5 + as + fs * 0.6, { italic: true });

  var ro = document.getElementById('readout');
  if (ro) {
    ro.innerHTML = 'a = ' + a.toFixed(1) + ', b = ' + b.toFixed(1) +
      '<br>c = √(' + (a * a).toFixed(1) + ' − ' + (b * b).toFixed(1) + ') = ' + c.toFixed(2) +
      '<br>2a = ' + (2 * a).toFixed(1) + ' (focal sum), e = c/a = ' + (c / a).toFixed(2);
  }
}

/* ---------- controls ---------- */
function syncSliders() {
  var A = document.getElementById('semiMajorAInput'), B = document.getElementById('semiMinorBInput');
  if (A) { A.value = state.a; document.getElementById('semiMajorAVal').value = state.a.toFixed(1); }
  if (B) { B.value = state.b; document.getElementById('semiMinorBVal').value = state.b.toFixed(1); }
  var L = document.getElementById('labelModeInput'); if (L) L.checked = state.params;
  var P = document.getElementById('dragPointOnEllipseInput'); if (P) P.checked = state.showP;
}

function update_semiMajorA(v) {
  state.a = v;
  if (state.b > state.a) state.b = state.a;
  syncSliders();
  relayout();
}
function update_semiMinorB(v) {
  state.b = Math.min(v, state.a);
  syncSliders();
  relayout();
}
function toggle_labelMode(on) { state.params = !!on; render(); }
function toggle_dragPointOnEllipse(on) { state.showP = !!on; render(); }

/* ---------- drag ---------- */
var dragging = false;
function setThetaFromEvent(e) {
  var rect = draw.node.getBoundingClientRect();
  var x = e.clientX - rect.left, y = e.clientY - rect.top;
  var wx = (x - plotX(0)) / scale, wy = (plotY(0) - y) / scale;
  var b = Math.min(state.b, state.a);
  if (Math.abs(wx) < 1e-6 && Math.abs(wy) < 1e-6) return;
  state.theta = Math.atan2(wy / b, wx / state.a);
  render();
}
draw.node.addEventListener('pointerdown', function (e) {
  if (!state.showP) return;
  dragging = true;
  try { draw.node.setPointerCapture(e.pointerId); } catch (err) { }
  setThetaFromEvent(e);
});
draw.node.addEventListener('pointermove', function (e) { if (dragging) setThetaFromEvent(e); });
window.addEventListener('pointerup', function () { dragging = false; });

/* ---------- demo steps ---------- */
var steps = [
  { title: 'The named parts',
    narration: 'A horizontal ellipse centered at the origin. The red dashed major axis runs between the two vertices; the red dashed minor axis runs between the two co-vertices; two green foci sit on the major axis inside the vertices.',
    state: { a: 6, b: 4, params: false, showP: false } },
  { title: 'Stretch the major axis',
    narration: 'Increase a and only the width changes: the vertices slide outward, the co-vertices never move, and the foci spread farther apart as the ellipse grows more elongated.',
    state: { a: 8, b: 4, params: false, showP: false } },
  { title: 'Stretch the minor axis',
    narration: 'Now hold a and raise b: the co-vertices rise, the vertices stay anchored at ±a, and the foci creep toward the center because c = √(a² − b²) shrinks.',
    state: { a: 8, b: 7, params: false, showP: false } },
  { title: 'When a = b the ellipse is a circle',
    narration: 'Set b equal to a and c becomes zero — both foci collapse onto the center, the axes become equal, and the ellipse is just a circle of radius a.',
    state: { a: 6, b: 6, params: false, showP: false } },
  { title: 'From parts to equation',
    narration: 'Switch to parameter labels: center-to-vertex is a, center-to-co-vertex is b, center-to-focus is c, feeding straight into x²/a² + y²/b² = 1 with c² = a² − b².',
    state: { a: 6, b: 4, params: true, showP: false } },
  { title: 'The focal definition',
    narration: 'Drag the orange point around the curve and watch the two focal distances trade off — their sum is always 2a, the full length of the major axis.',
    state: { a: 6, b: 3, params: true, showP: true } }
];
var stepIdx = 0;

function applyStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[stepIdx];
  state.a = s.state.a;
  state.b = Math.min(s.state.b, s.state.a);
  state.params = s.state.params;
  state.showP = s.state.showP;
  syncSliders();
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = 'Step ' + (stepIdx + 1) + ' / ' + steps.length + ' — ' + s.title;
  relayout();
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

/* ---------- init ---------- */
applyStep(0);
window.__markRendered();
