   oninput="document.getElementById('semiMinorBVal').value=(+this.value).toFixed(1);update_semiMinorB(+this.value)"></label>
<label style="flex-direction:row;align-items:center;gap:5px"><input id="labelModeInput" type="checkbox" onchange="toggle_labelMode(this.checked)"> Label mode: equation parameters</label>
<label style="flex-direction:row;align-items:center;gap:5px"><input id="dragPointOnEllipseInput" type="checkbox" onchange="toggle_dragPointOnEllipse(this.checked)"> Draggable point P (focal sum)</label>
